"""Strata SDK exceptions."""


class StrataError(Exception):
    """Base exception for all Strata SDK errors."""


class StrataConnectionError(StrataError):
    """Failed to connect to Strata MCP server."""


class StrataNotFoundError(StrataError):
    """Strata MCP server binary not found. Install with: npm install -g strata-mcp"""


class StrataTimeoutError(StrataError):
    """Operation timed out."""


class StrataProtocolError(StrataError):
    """MCP protocol error — unexpected response from server."""

    def __init__(self, message: str, raw_response: str | None = None) -> None:
        super().__init__(message)
        self.raw_response = raw_response
